@@ -0,0 +1,189 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Layouts
+
+import org.kde.plasma.plasmoid
+import org.kde.plasma.core as PlasmaCore
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+import org.kde.kirigami as Kirigami
+import org.kde.kcmutils as KCM
+
+import plasma.applet.org.kde.plasma.keyboardshortcuts as Private
+
+PlasmoidItem {
+    id: root
+
+    readonly property bool inPanel: (Plasmoid.location === PlasmaCore.Types.TopEdge
+        || Plasmoid.location === PlasmaCore.Types.RightEdge
+        || Plasmoid.location === PlasmaCore.Types.BottomEdge
+        || Plasmoid.location === PlasmaCore.Types.LeftEdge)
+
+    switchWidth: Kirigami.Units.gridUnit * 12
+    switchHeight: Kirigami.Units.gridUnit * 12
+
+    Plasmoid.icon: inPanel ? "preferences-desktop-keyboard-shortcut-symbolic" : "preferences-desktop-keyboard-shortcut"
+    toolTipSubText: i18nc("@info:tooltip", "Find a keyboard shortcut by its name or its keys")
+
+    Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            text: i18nc("@action:inmenu", "Configure Keyboard Shortcuts…")
+            icon.name: "configure-shortcuts"
+            onTriggered: KCM.KCMLauncher.openSystemSettings("kcm_keys")
+        }
+    ]
+
+    Private.ShortcutsModel {
+        id: shortcutsModel
+    }
+
+    onExpandedChanged: {
+        if (expanded) {
+            shortcutsModel.reload();
+        }
+    }
+
+    fullRepresentation: PlasmaComponents3.Page {
+        Layout.minimumWidth: Kirigami.Units.gridUnit * 14
+        Layout.minimumHeight: Kirigami.Units.gridUnit * 14
+        Layout.preferredWidth: Kirigami.Units.gridUnit * 24
+        Layout.preferredHeight: Kirigami.Units.gridUnit * 26
+
+        header: PlasmaExtras.PlasmoidHeading {
+            RowLayout {
+                anchors.fill: parent
+                spacing: Kirigami.Units.smallSpacing
+
+                PlasmaExtras.SearchField {
+                    id: searchField
+                    Layout.fillWidth: true
+
+                    onTextChanged: {
+                        shortcutsModel.filter = text;
+                        listView.currentIndex = 0;
+                    }
+
+                    KeyNavigation.down: listView
+                    Keys.onReturnPressed: (listView.currentItem as PlasmaComponents3.ItemDelegate)?.clicked()
+                    Keys.onEnterPressed: Keys.returnPressed()
+                    Keys.onEscapePressed: event => {
+                        if (text !== "") {
+                            text = "";
+                        } else {
+                            root.expanded = false;
+                        }
+                    }
+                }
+
+                PlasmaComponents3.ToolButton {
+                    icon.name: "configure-symbolic"
+                    display: PlasmaComponents3.AbstractButton.IconOnly
+                    text: i18nc("@action:button", "Configure Keyboard Shortcuts…")
+                    onClicked: KCM.KCMLauncher.openSystemSettings("kcm_keys")
+
+                    PlasmaComponents3.ToolTip.text: text
+                    PlasmaComponents3.ToolTip.visible: hovered
+                    PlasmaComponents3.ToolTip.delay: Kirigami.Units.toolTipDelay
+                }
+            }
+        }
+
+        PlasmaComponents3.ScrollView {
+            anchors.fill: parent
+
+            contentItem: ListView {
+                id: listView
+
+                model: shortcutsModel
+                clip: true
+                keyNavigationWraps: true
+                highlight: PlasmaExtras.Highlight {}
+                highlightMoveDuration: 0
+                highlightResizeDuration: 0
+
+                Keys.onReturnPressed: (currentItem as PlasmaComponents3.ItemDelegate)?.clicked()
+                Keys.onEnterPressed: Keys.returnPressed()
+                Keys.onUpPressed: event => {
+                    if (currentIndex === 0) {
+                        searchField.forceActiveFocus(Qt.BacktabFocusReason);
+                    } else {
+                        event.accepted = false;
+                    }
+                }
+
+                section.property: "componentName"
+                section.delegate: PlasmaExtras.ListSectionHeader {
+                    required property string section
+
+                    width: ListView.view.width
+                    text: section
+                }
+
+                delegate: PlasmaComponents3.ItemDelegate {
+                    id: delegate
+
+                    required property int index
+                    required property var model
+
+                    width: ListView.view.width
+                    text: model.display
+                    Accessible.description: model.shortcutsText
+
+                    contentItem: RowLayout {
+                        spacing: Kirigami.Units.largeSpacing
+
+                        PlasmaComponents3.Label {
+                            Layout.fillWidth: true
+                            text: delegate.model.display
+                            elide: Text.ElideRight
+                            textFormat: Text.PlainText
+                        }
+
+                        PlasmaComponents3.Label {
+                            Layout.maximumWidth: delegate.width / 2
+                            text: delegate.model.shortcutsText
+                            elide: Text.ElideLeft
+                            textFormat: Text.PlainText
+                            opacity: 0.7
+                        }
+                    }
+
+                    onHoveredChanged: {
+                        if (hovered) {
+                            ListView.view.currentIndex = index;
+                        }
+                    }
+                    onClicked: {
+                        root.expanded = false;
+                        shortcutsModel.invoke(index);
+                    }
+                }
+
+                PlasmaExtras.PlaceholderMessage {
+                    anchors.centerIn: parent
+                    width: parent.width - Kirigami.Units.gridUnit * 4
+                    visible: listView.count === 0 && !shortcutsModel.loading
+                    iconName: searchField.text !== "" ? "edit-none" : "preferences-desktop-keyboard-shortcut"
+                    text: searchField.text !== "" ? i18nc("@info:placeholder", "No matching shortcuts") : i18nc("@info:placeholder", "No shortcuts")
+                }
+            }
+        }
+
+        Connections {
+            target: root
+            function onExpandedChanged() {
+                if (root.expanded) {
+                    searchField.text = "";
+                    listView.currentIndex = 0;
+                    searchField.forceActiveFocus(Qt.PopupFocusReason);
+                }
+            }
+        }
+    }
+}
