index 0000000000..8d4ee17f85
--- /dev/null
+++ b/applets/keyboardshortcuts/shortcutsmodel.cpp
@@ -0,0 +1,143 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "shortcutsmodel.h"
+
+#include <QCollator>
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QKeySequence>
+
+#include <algorithm>
+
+#include <KDescendantsProxyModel>
+
+#include "basemodel.h"
+#include "filteredmodel.h"
+#include "globalaccelmodel.h"
+
+using namespace Qt::StringLiterals;
+
+class ActiveShortcutsModel : public FilteredShortcutsModel
+{
+public:
+    using FilteredShortcutsModel::FilteredShortcutsModel;
+
+    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override
+    {
+        // Components are shown through recursive filtering when one of their actions is
+        if (!sourceParent.isValid()) {
+            return false;
+        }
+        const QModelIndex index = sourceModel()->index(sourceRow, 0, sourceParent);
+        if (index.data(BaseModel::ActiveShortcutsRole).value<QSet<QKeySequence>>().isEmpty()) {
+            return false;
+        }
+        return FilteredShortcutsModel::filterAcceptsRow(sourceRow, sourceParent);
+    }
+};
+
+ShortcutsModel::ShortcutsModel(QObject *parent)
+    : QSortFilterProxyModel(parent)
+    , m_globalAccelModel(new GlobalAccelModel(this))
+    , m_activeModel(new ActiveShortcutsModel(this))
+    , m_flatModel(new KDescendantsProxyModel(this))
+{
+    m_activeModel->setSourceModel(m_globalAccelModel);
+    m_flatModel->setSourceModel(m_activeModel);
+    setSourceModel(m_flatModel);
+
+    connect(m_globalAccelModel, &QAbstractItemModel::modelReset, this, [this] {
+        m_loading = false;
+        Q_EMIT loadingChanged();
+    });
+    connect(m_activeModel, &FilteredShortcutsModel::filterChanged, this, &ShortcutsModel::filterChanged);
+
+    reload();
+}
+
+QVariant ShortcutsModel::data(const QModelIndex &index, int role) const
+{
+    const QModelIndex activeIndex = m_flatModel->mapToSource(mapToSource(index));
+    switch (role) {
+    case ComponentNameRole:
+        return activeIndex.parent().data(Qt::DisplayRole);
+    case ShortcutsTextRole: {
+        const auto shortcuts = activeIndex.data(BaseModel::ActiveShortcutsRole).value<QSet<QKeySequence>>();
+        QStringList texts;
+        for (const QKeySequence &shortcut : shortcuts) {
+            texts.append(shortcut.toString(QKeySequence::NativeText));
+        }
+        QCollator collator;
+        std::sort(texts.begin(), texts.end(), collator);
+        return texts.join(u", ");
+    }
+    }
+    return QSortFilterProxyModel::data(index, role);
+}
+
+QHash<int, QByteArray> ShortcutsModel::roleNames() const
+{
+    QHash<int, QByteArray> roles = QSortFilterProxyModel::roleNames();
+    roles.insert(ComponentNameRole, "componentName");
+    roles.insert(ShortcutsTextRole, "shortcutsText");
+    return roles;
+}
+
+QString ShortcutsModel::filter() const
+{
+    return m_activeModel->filter();
+}
+
+void ShortcutsModel::setFilter(const QString &filter)
+{
+    m_activeModel->setFilter(filter);
+}
+
+bool ShortcutsModel::loading() const
+{
+    return m_loading;
+}
+
+void ShortcutsModel::reload()
+{
+    if (m_loading || !m_globalAccelModel->isValid()) {
+        return;
+    }
+    m_loading = true;
+    Q_EMIT loadingChanged();
+    m_globalAccelModel->load();
+}
+
+void ShortcutsModel::invoke(int row)
+{
+    const QModelIndex activeIndex = m_flatModel->mapToSource(mapToSource(index(row, 0)));
+    if (!activeIndex.parent().isValid()) {
+        return;
+    }
+    QString dbusPath = activeIndex.parent().data(BaseModel::ComponentRole).toString();
+    // D-Bus paths can only contain ASCII letters, digits and '_'
+    std::replace_if(
+        dbusPath.begin(),
+        dbusPath.end(),
+        [](QChar ch) {
+            const char16_t c = ch.unicode();
+            return !(c == '_' || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
+        },
+        u'_');
+    QDBusMessage msg =
+        QDBusMessage::createMethodCall(u"org.kde.kglobalaccel"_s, u"/component/" + dbusPath, u"org.kde.kglobalaccel.Component"_s, u"invokeShortcut"_s);
+    msg << activeIndex.data(BaseModel::ActionRole).toString();
+    QDBusConnection::sessionBus().call(msg, QDBus::NoBlock);
+}
+
+bool ShortcutsModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const
+{
+    // Only actions, their components become section headers
+    return m_flatModel->mapToSource(m_flatModel->index(sourceRow, 0, sourceParent)).parent().isValid();
+}
+
+#include "moc_shortcutsmodel.cpp"
diff --git a/applets/keyboardshortcuts/shortcutsmodel.h b/applets/keyboardshortcuts/shortcutsmodel.h
new file mode 100644
index 0000000000..7a2131dc3c
--- /dev/null
+++ b/applets/keyboardshortcuts/shortcutsmodel.h
@@ -0,0 +1,57 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QQmlEngine>
+#include <QSortFilterProxyModel>
+
+class KDescendantsProxyModel;
+class GlobalAccelModel;
+class ActiveShortcutsModel;
+
+// Flat list of the global shortcuts that have a key assigned, for a ListView with sections
+class ShortcutsModel : public QSortFilterProxyModel
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(QString filter READ filter WRITE setFilter NOTIFY filterChanged)
+    Q_PROPERTY(bool loading READ loading NOTIFY loadingChanged)
+
+public:
+    enum Roles {
+        ComponentNameRole = Qt::UserRole + 100,
+        ShortcutsTextRole,
+    };
+    Q_ENUM(Roles)
+
+    explicit ShortcutsModel(QObject *parent = nullptr);
+
+    QVariant data(const QModelIndex &index, int role = Qt::DisplayRole) const override;
+    QHash<int, QByteArray> roleNames() const override;
+
+    QString filter() const;
+    void setFilter(const QString &filter);
+
+    bool loading() const;
+
+    Q_INVOKABLE void reload();
+    Q_INVOKABLE void invoke(int row);
+
+Q_SIGNALS:
+    void filterChanged();
+    void loadingChanged();
+
+protected:
+    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override;
+
+private:
+    GlobalAccelModel *m_globalAccelModel;
+    ActiveShortcutsModel *m_activeModel;
+    KDescendantsProxyModel *m_flatModel;
+    bool m_loading = false;
+};
